using System.Text;
using AuditSphereOps.Domain.Tests;
using Microsoft.EntityFrameworkCore;
using Microsoft.Playwright;
namespace AuditSphereOps.E2E.Tests;

public sealed class AngularGeneralLedgerUploadJourneyTests
{
    [Fact]
    [Trait("CaseId", "ANGULAR-GL-UPLOAD")]
    public async Task LostResponse_ReloadExactFile_ReceiptsPreventDuplicates_MobileAndRevocation() { await using var host = await OwnedHost.StartAsync(startWorker: false, caseId: "ANGULAR-GL-UPLOAD"); await Seed(host); var origin = await host.StartApiForIdentityAsync(host.Fixture.Staff, new Dictionary<string, string> { ["AngularUi__Enabled"] = "true" }); using var pw = await Playwright.CreateAsync(); await using var browser = await PlaywrightBrowser.LaunchAsync(pw); var page = await browser.NewPageAsync(); var errors = new List<string>(); page.PageError += (_, e) => errors.Add(e); await page.GotoAsync(origin + "/auth/sign-in?returnUrl=" + Uri.EscapeDataString($"/ui/app/engagements/{host.Fixture.EngagementId}/general-ledger")); await page.GetByRole(AriaRole.Link, new() { Name = "Upload general ledger", Exact = true }).ClickAsync(); await Pick(page, GeneralLedgerUploadSeed.Csv); await Assertions.Expect(page.GetByRole(AriaRole.Region, new() { Name = "GL upload sample", Exact = true })).ToContainTextAsync("100.123456"); await page.GetByLabel(Assent, new() { Exact = true }).CheckAsync(); var writes = 0; await page.RouteAsync("**/general-ledger/import", async r => { writes++; var response = await r.FetchAsync(); Assert.Equal(200, response.Status); await r.AbortAsync("failed"); }); await page.GetByRole(AriaRole.Button, new() { Name = "Import reviewed GL file", Exact = true }).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Heading, new() { Name = "GL import outcome needs review", Exact = true })).ToBeVisibleAsync(); await page.ReloadAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Heading, new() { Name = "GL import outcome needs review", Exact = true })).ToBeVisibleAsync(); await Pick(page, GeneralLedgerUploadSeed.Csv.Replace("Source user", "Wrong file")); await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("mismatched"); await Pick(page, GeneralLedgerUploadSeed.Csv); await page.GetByRole(AriaRole.Button, new() { Name = "I reviewed the persisted GL source", Exact = true }).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Button, new() { Name = "Import reviewed GL file", Exact = true })).ToBeDisabledAsync(); await Assertions.Expect(page.Locator("body")).ToContainTextAsync("SEALED"); Assert.Equal(1, writes); await page.SetViewportSizeAsync(390, 844); Assert.True(await page.EvaluateAsync<bool>("() => document.documentElement.scrollWidth <= window.innerWidth + 1")); await using (var db = host.CreateDbContext()) { Assert.Single(await db.SourceImportBatches.ToListAsync()); Assert.Equal(2, await db.GeneralLedgerLines.CountAsync()); Assert.Empty(await db.SourceAcceptanceDecisions.ToListAsync()); await db.Users.Where(x => x.Id == host.Fixture.Staff.Id).ExecuteUpdateAsync(s => s.SetProperty(x => x.SessionEpoch, x => x.SessionEpoch + 1)); } await Assertions.Expect(page.GetByRole(AriaRole.Heading, new() { Name = "Access unavailable", Exact = true })).ToBeVisibleAsync(new() { Timeout = 15000 }); Assert.DoesNotContain("100.123456", await page.Locator("body").InnerTextAsync()); Assert.Empty(errors); }
    [Fact]
    [Trait("CaseId", "ANGULAR-GL-UPLOAD-GATES")]
    public async Task MalformedPreview_Navigation_StaleReviewAndFreshImport() { await using var host = await OwnedHost.StartAsync(startWorker: false, caseId: "ANGULAR-GL-UPLOAD-GATES"); await Seed(host); var origin = await host.StartApiForIdentityAsync(host.Fixture.Staff, new Dictionary<string, string> { ["AngularUi__Enabled"] = "true" }); using var pw = await Playwright.CreateAsync(); await using var browser = await PlaywrightBrowser.LaunchAsync(pw); var page = await browser.NewPageAsync(); await page.GotoAsync(origin + "/auth/sign-in?returnUrl=" + Uri.EscapeDataString($"/ui/app/engagements/{host.Fixture.EngagementId}/general-ledger/upload")); await Pick(page, GeneralLedgerUploadSeed.Csv.Replace("100.123456", "1e2")); await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("exact decimal"); await Pick(page, GeneralLedgerUploadSeed.Csv); await Assertions.Expect(page.GetByRole(AriaRole.Region, new() { Name = "GL upload sample", Exact = true })).ToContainTextAsync("100.123456"); await page.GetByRole(AriaRole.Link, new() { Name = "Back to general ledger inspection", Exact = true }).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Dialog)).ToBeVisibleAsync(); await page.GetByRole(AriaRole.Button, new() { Name = "Keep editing", Exact = true }).ClickAsync(); await page.GetByLabel(Assent, new() { Exact = true }).CheckAsync(); await using (var db = host.CreateDbContext()) await db.ClientSafetyStates.Where(x => x.Id == host.Fixture.ClientId).ExecuteUpdateAsync(s => s.SetProperty(x => x.InputGeneration, x => x.InputGeneration + 1)); await page.GetByRole(AriaRole.Button, new() { Name = "Import reviewed GL file", Exact = true }).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("changed"); await page.GetByRole(AriaRole.Button, new() { Name = "Read persisted GL source", Exact = true }).ClickAsync(); await page.GetByLabel(Assent, new() { Exact = true }).CheckAsync(); await page.GetByRole(AriaRole.Button, new() { Name = "Import reviewed GL file", Exact = true }).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("sealed and retained"); await Assertions.Expect(page.GetByRole(AriaRole.Link, new() { Name = "Review imported GL source acceptance", Exact = true })).ToBeVisibleAsync(); await using var proof = host.CreateDbContext(); Assert.Single(await proof.SourceImportBatches.ToListAsync()); }
    private const string Assent = "I reviewed this exact GL file, reporting context and complete server validation.";
    private static Task Pick(IPage page, string csv) => page.GetByLabel("General ledger CSV file", new() { Exact = true }).SetInputFilesAsync(new FilePayload { Name = "synthetic-ledger.csv", MimeType = "text/csv", Buffer = Encoding.UTF8.GetBytes(csv) });
    private static async Task<GeneralLedgerUploadSeed.Context> Seed(OwnedHost host) { await using var db = host.CreateDbContext(); return await GeneralLedgerUploadSeed.SeedAsync(db, host.Fixture); }
}
